<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/services-fixture.php';
use Hostider\Core\Database\Migrator;use Hostider\Core\Id;use Hostider\Core\Http\HttpError;use Hostider\Services\State;
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();
test('F3-A service state rejects activation without provisioning and terminated resurrection',function(): void {State::assertTransition('QUEUED','PROVISIONING');State::assertTransition('PROVISIONING','ACTIVE');same(409,raises(HttpError::class,fn()=>State::assertTransition('QUEUED','ACTIVE'))->status);same(409,raises(HttpError::class,fn()=>State::assertTransition('TERMINATED','ACTIVE'))->status);});
test('F3-A multi-unit canonical paid order freezes configs prices periods and ownership once',function()use($db): void {
    $f=serviceFixture($db,3);$total='0';for($unit=1;$unit<=3;++$unit){$row=$db->transaction(fn()=>$f['repository']->materialize($f['order'],$f['item'],$f['line'],$unit,$f['category'],$f['actor'],Id::uuid()));same('QUEUED',$row['status']);same($row['id'],$db->transaction(fn()=>$f['repository']->materialize($f['order'],$f['item'],$f['line'],$unit,$f['category'],$f['actor'],Id::uuid()))['id']);same(\Hostider\Core\CanonicalJson::encode($f['line']),\Hostider\Core\CanonicalJson::encode($f['repository']->configuration($row['id'])['original_line']));$price=$db->execute('SELECT * FROM svc_prices WHERE service_id=?',[$row['id']])->fetch();$total=(string)(new \Hostider\Finance\Decimal($total))->add(new \Hostider\Finance\Decimal((string)$price['total_minor']));same(1,(int)$db->execute('SELECT COUNT(*) FROM svc_periods WHERE service_id=?',[$row['id']])->fetchColumn());raises(PDOException::class,fn()=>$db->execute('UPDATE svc_prices SET total_minor=0 WHERE id=?',[$price['id']]));}same($f['line']['total_minor'],$total);same(3,(int)$db->execute('SELECT COUNT(*) FROM svc_services WHERE order_item_id=?',[$f['item']['id']])->fetchColumn());
});
test('F3-A unpaid cancelled refunded forged and legacy sources fail closed',function()use($db): void {
    $unpaid=serviceFixture($db,1,false,false);same(409,raises(HttpError::class,fn()=>$db->transaction(fn()=>$unpaid['repository']->materialize($unpaid['order'],$unpaid['item'],$unpaid['line'],1,$unpaid['category'],$unpaid['actor'],Id::uuid())))->status);$f=serviceFixture($db);$line=$f['line'];$line['total_minor']='1';same(409,raises(HttpError::class,fn()=>$db->transaction(fn()=>$f['repository']->materialize($f['order'],$f['item'],$line,1,$f['category'],$f['actor'],Id::uuid())))->status);$legacy=$f['order'];$legacy['origin_environment']='LEGACY_UNKNOWN';same(403,raises(HttpError::class,fn()=>$db->transaction(fn()=>$f['repository']->materialize($legacy,$f['item'],$f['line'],1,$f['category'],$f['actor'],Id::uuid())))->status);$db->execute("UPDATE orders SET status='CANCELLED',refund_status='FULL' WHERE id=?",[$f['order']['id']]);same(409,raises(HttpError::class,fn()=>$db->transaction(fn()=>$f['repository']->materialize($f['order'],$f['item'],$f['line'],1,$f['category'],$f['actor'],Id::uuid())))->status);
});
test('F3-A manual service and transaction rollback preserve history and customer isolation',function()use($db): void {
    $f=serviceFixture($db,1,true);$row=$db->transaction(fn()=>$f['repository']->materialize($f['order'],$f['item'],$f['line'],1,$f['category'],$f['actor'],Id::uuid()));same('PENDING_APPROVAL',$row['status']);same(404,raises(HttpError::class,fn()=>$f['repository']->find($row['id'],Id::uuid(),false))->status);raises(RuntimeException::class,fn()=>$db->transaction(function()use($f,$row): void{$f['repository']->transition($row,'QUEUED',$f['actor'],Id::uuid());throw new RuntimeException('Injected rollback');}));same('PENDING_APPROVAL',$f['repository']->find($row['id'],lock:false)['status']);
});
test('F3-A imported resources never enter create and test provenance cannot be promoted',function()use($db): void{
    $f=serviceFixture($db);$service=Id::uuid();$operation=Id::uuid();$db->transaction(function()use($db,$f,$service,$operation): void{$db->execute("INSERT INTO svc_services(id,customer_id,order_id,unit_no,product_id,name,origin_environment,imported,status,current_operation_id) VALUES (?,?,?,1,?,'Imported synthetic resource','LEGACY_UNKNOWN',TRUE,'QUEUED',?)",[$service,$f['customer'],$f['order']['id'],$f['product'],$operation]);$db->execute("INSERT INTO svc_operations(id,service_id,order_item_id,kind,generation,request_fingerprint) VALUES (?,?,?,'CREATE',1,?)",[$operation,$service,$f['item']['id'],str_repeat('0',64)]);});$before=$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn();same(409,raises(HttpError::class,fn()=>(new \Hostider\Services\Engine($db,$f['config']))->claim($f['actor'],Id::uuid(),$operation,true))->status);raises(PDOException::class,fn()=>$db->execute("UPDATE svc_services SET origin_environment='test',imported=FALSE WHERE id=?",[$service]));foreach(['staging','production'] as $environment){$config=new \Hostider\Core\Config($environment,$f['config']->url,$f['config']->key,$f['config']->dsn,$f['config']->dbUser,$f['config']->dbPassword);same(403,raises(HttpError::class,fn()=>(new \Hostider\Services\Engine($db,$config))->discover($f['order']['id'],$f['actor'],Id::uuid()))->status);}same($before,$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn());same(0,(int)$db->execute('SELECT COUNT(*) FROM svc_resources WHERE service_id=?',[$service])->fetchColumn());
});
test('F3-A one paid multi-product multi-unit order creates exactly five independently verified resources',function()use($db): void{
    $f=serviceFixture($db);$product=$f['create']('product-create',['name'=>'Second synthetic hosting','category_id'=>$f['category'],'product_type'=>'HOSTING','pricing_strategy'=>'FIXED_THEN_FX','source_currency'=>'USD','activation_policy'=>'AUTO','refund_policy'=>'staff_approval']);$f['create']('price-publish',['item_id'=>$product,'cycle_id'=>$f['cycle'],'currency'=>'USD','amount'=>'5']);$f['create']('product-status',['id'=>$product,'version'=>1,'sale_status'=>'ACTIVE']);$cart=$f['cart'];$cart[0]['quantity']=2;$cart[]=['product_id'=>$product,'cycle_id'=>$f['cycle'],'quantity'=>3];$order=$db->transaction(function()use($f,$cart): array{$quote=$f['quotes']->issue($f['quotes']->plan($f['customer'],new \Hostider\Finance\Currency('USD'),$cart,[],$f['now']));$order=$f['orders']->submit($quote['id'],$f['customer'],['name'=>'Synthetic multi product','currency'=>'USD'],$f['actor'],Id::uuid(),$f['now']);$money=new \Hostider\Finance\Money($quote['total_minor'],new \Hostider\Finance\Currency('USD'));$payment=$f['finance']->recordTestCollection($f['customer'],$money,Id::uuid(),$f['actor'],Id::uuid());$f['orders']->fund($order['id'],$f['customer'],$money,'COLLECTION',$payment,Id::uuid(),$f['actor'],Id::uuid());return $order;});$pools=new \Hostider\Hosting\Pools($db,$f['config']);$pools->configure($f['product'],10);$pools->configure($product,10);$engine=new \Hostider\Services\Engine($db,$f['config']);$ids=$engine->discover($order['id'],$f['actor'],Id::uuid());same(5,count($ids));$ledger=$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn();foreach($ids as $id){$operation=$engine->repository->find($id,lock:false)['current_operation_id'];$worker=new \Hostider\Services\Worker($db,$f['config']);same(true,$worker->once($f['actor'],$operation));same(false,$worker->once($f['actor'],$operation));same('ACTIVE',$engine->repository->find($id,lock:false)['status']);}same(2,(int)$db->execute('SELECT COUNT(DISTINCT order_item_id) FROM svc_services WHERE order_id=?',[$order['id']])->fetchColumn());same(5,(int)$db->execute('SELECT COUNT(*) FROM svc_resources r JOIN svc_services s ON s.id=r.service_id WHERE s.order_id=?',[$order['id']])->fetchColumn());same(5,(int)$db->execute('SELECT COUNT(*) FROM mock_hosting_accounts a JOIN svc_services s ON s.id=a.service_id WHERE s.order_id=?',[$order['id']])->fetchColumn());same($ledger,$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn());
});
runTests();
